const settleCharge = `-- name: SettleCharge :one
UPDATE charges SET status = 'paid', payment_method = $1, settled_by = $2, settled_at = now(), updated_at = now()
WHERE tenant_id = $3 AND id = $4 AND status = 'pending' AND deleted_at IS NULL
RETURNING id, source, patient_id, branch_id, department_id, to_triage, provider_id, enqueued
`

type SettleChargeParams struct {
	PaymentMethod *string    `json:"payment_method"`
	SettledBy     *uuid.UUID `json:"settled_by"`
	TenantID      uuid.UUID  `json:"tenant_id"`
	ID            uuid.UUID  `json:"id"`
}

type SettleChargeRow struct {
	ID           uuid.UUID  `json:"id"`
	Source       string     `json:"source"`
	PatientID    uuid.UUID  `json:"patient_id"`
	BranchID     *uuid.UUID `json:"branch_id"`
	DepartmentID *uuid.UUID `json:"department_id"`
	ToTriage     bool       `json:"to_triage"`
	ProviderID   *uuid.UUID `json:"provider_id"`
	Enqueued     bool       `json:"enqueued"`
}

// Atomic claim: only a pending charge can be settled (prevents double-collect).
func (q *Queries) SettleCharge(ctx context.Context, arg SettleChargeParams) (SettleChargeRow, error) {
	row := q.db.QueryRow(ctx, settleCharge,
		arg.PaymentMethod,
		arg.SettledBy,
		arg.TenantID,
		arg.ID,
	)
	var i SettleChargeRow
	err := row.Scan(
		&i.ID,
		&i.Source,
		&i.PatientID,
		&i.BranchID,
		&i.DepartmentID,
		&i.ToTriage,
		&i.ProviderID,
		&i.Enqueued,
	)
	return i, err
}

const settleVisit = `-- name: SettleVisit :many
UPDATE charges SET status = 'paid', payment_method = $1, settled_by = $2,
  settled_at = now(), receipt_no = $3, updated_at = now()
WHERE tenant_id = $4 AND patient_id = $5 AND status = 'pending' AND deleted_at IS NULL
RETURNING id, amount, branch_id, department_id, to_triage, provider_id
`

type SettleVisitParams struct {
	PaymentMethod *string    `json:"payment_method"`
	SettledBy     *uuid.UUID `json:"settled_by"`
	ReceiptNo     *int64     `json:"receipt_no"`
	TenantID      uuid.UUID  `json:"tenant_id"`
	PatientID     uuid.UUID  `json:"patient_id"`
}

type SettleVisitRow struct {
	ID           uuid.UUID  `json:"id"`
	Amount       string     `json:"amount"`
	BranchID     *uuid.UUID `json:"branch_id"`
	DepartmentID *uuid.UUID `json:"department_id"`
	ToTriage     bool       `json:"to_triage"`
	ProviderID   *uuid.UUID `json:"provider_id"`
}

// One-click visit checkout: settle ALL of a patient's pending charges in a single
// statement, sharing one receipt number. Returns routing so the patient advances once.
func (q *Queries) SettleVisit(ctx context.Context, arg SettleVisitParams) ([]SettleVisitRow, error) {
	rows, err := q.db.Query(ctx, settleVisit,
		arg.PaymentMethod,
		arg.SettledBy,
		arg.ReceiptNo,
		arg.TenantID,
		arg.PatientID,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SettleVisitRow{}
	for rows.Next() {
		var i SettleVisitRow
		if err := rows.Scan(
			&i.ID,
			&i.Amount,
			&i.BranchID,
			&i.DepartmentID,
			&i.ToTriage,
			&i.ProviderID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

